// The synthetic physical bytes at a fixed ROM / bank offset (rules below).
std::uint32_t synthetic(std::uint32_t address,unsigned int n){
 for(unsigned int i=0;i<SYNTHETIC_COUNT;++i){const Bytes b=hex_bytes(SYNTHETIC[i].bytes);
  if(address>=SYNTHETIC[i].address&&address+n<=SYNTHETIC[i].address+b.size()){std::uint32_t v=0;for(unsigned int k=0;k<n;++k)v=(v<<8)|b[address-SYNTHETIC[i].address+k];return v;}}
 return 0xffffffffU;}
std::vector<std::uint8_t> pvc_base(){std::vector<std::uint8_t> p(8192,0);p[0x1ff1]=0xa0;p[0x1ff2]=0x10;return p;}
// "address:hexbytes,..." -> bytes written in order (24-bit addresses, work RAM mirror).
void apply(Bytes&b,const char*text){
 const char*p=text;while(*p){char*end=NULL;const std::uint32_t a=static_cast<std::uint32_t>(std::strtoul(p,&end,16));check(end!=NULL&&*end==':',"puts syntax");p=end+1;
  std::uint32_t at=a;while(*p&&*p!=','){b[at&65535U]=static_cast<std::uint8_t>((hex_digit(p[0])<<4)|hex_digit(p[1]));p+=2;++at;}if(*p==',')++p;}}
Bytes base_ram(const char*puts){Bytes ram(65536,0);put(ram,SP,4,STOP);apply(ram,puts);return ram;}
struct Out {ms5::AnimationMachineDevice dev;std::vector<ms5::VideoPortWrite> ports;std::uint32_t reads;ms5::AnimationMachineStatus status;std::string error;
 Out():reads(99),status(ms5::AnimationMachineWaiting){dev.bank_base=0x200000;dev.pvc=pvc_base();ms5::VideoPortWrite p;p.address=0xdeadbeef;p.size=1;p.value=0x87;ports.push_back(p);}};
ms5::ProgramBusState bus_of(){ms5::ProgramBusState bus;bus.physical_rom=&ROM;return bus;}
bool run(Bytes&ram,State&s,std::uint32_t stop,Out&o){++calls;const ms5::ProgramBusState bus=bus_of();std::vector<ms5::FixedDataResource> w;
 o.ports.clear();o.error.clear();
 const bool ok=ms5::run_animation_machine(ram,w,bus,s,o.dev,stop,0,o.reads,o.status,o.ports,o.error);
 if(!ok)std::cerr<<std::hex<<"run error "<<o.error<<" stop "<<stop<<"\n";return ok;}
bool run_rom(const Physical&rom,Bytes&ram,State&s,std::uint32_t stop){Out o;++calls;ms5::ProgramBusState bus;bus.physical_rom=&rom;std::vector<ms5::FixedDataResource> w;
 o.ports.clear();o.error.clear();
 const bool ok=ms5::run_animation_machine(ram,w,bus,s,o.dev,stop,0,o.reads,o.status,o.ports,o.error);
 if(!ok)std::cerr<<std::hex<<"run error "<<o.error<<" stop "<<stop<<"\n";return ok;}
bool same(const State&a,const State&b){for(unsigned int i=0;i<8;++i)if(a.d[i]!=b.d[i]||a.a[i]!=b.a[i])return false;return a.pc==b.pc&&a.carry==b.carry;}
ms5::AnimationCarryState carry_of(unsigned int i){return static_cast<ms5::AnimationCarryState>(i);}
// Failure preserves RAM, registers, device and every output.
void reject(Bytes ram,State s,std::uint32_t stop,const char*message){
 const Bytes before=ram;const State old=s;Out o;const ms5::AnimationMachineDevice dev=o.dev;
 ++calls;const ms5::ProgramBusState bus=bus_of();std::vector<ms5::FixedDataResource> w;
 const bool ok=ms5::run_animation_machine(ram,w,bus,s,o.dev,stop,0,o.reads,o.status,o.ports,o.error);
 if(ok)std::cerr<<std::hex<<"unexpected success "<<old.pc<<" stop "<<stop<<"\n";
 if(o.error!=message)std::cerr<<std::hex<<old.pc<<": "<<o.error<<" expected "<<message<<"\n";
 check(!ok&&o.error==message,"checked error",old.pc);
 check(ram==before&&same(s,old)&&dev.pvc==o.dev.pvc&&dev.bank_base==o.dev.bank_base&&o.reads==99&&
  o.status==ms5::AnimationMachineWaiting&&o.ports.size()==1&&o.ports[0].address==0xdeadbeef&&o.ports[0].value==0x87&&o.ports[0].size==1,
  "failure preserves every output",old.pc);}
// The failing PC of a checked error (review 0264 L-1): the same state run with stop = the failing PC ends there (when it differs from the entry and
// is even).
void fails_at(Bytes ram,State s,std::uint32_t fail,const char*message,std::uint32_t stop){
 reject(ram,s,stop,message);
 if(fail==s.pc||(fail&1U)!=0U)return;
 Out o;check(run(ram,s,fail,o)&&s.pc==fail&&o.status==ms5::AnimationMachineReturned,"the run reaches the failing PC",fail);}
// Digest: RAM, D0-D7, A0-A7, PC, bank, reads (BE LONGs), status.
unsigned long long digest(const Bytes&ram,const State&s,std::uint32_t bank,std::uint32_t reads,ms5::AnimationMachineStatus status){
 Bytes tail;for(unsigned int i=0;i<8;++i)long_be(tail,s.d[i]);for(unsigned int i=0;i<8;++i)long_be(tail,s.a[i]);
 long_be(tail,s.pc);long_be(tail,bank);long_be(tail,reads);tail.push_back(static_cast<std::uint8_t>(status));
 return fnv_add(fnv_add(1469598103934665603ULL,ram),tail);}
State state_of(const std::uint32_t*regs,std::uint32_t pc,unsigned int carry){State s;for(unsigned int i=0;i<8;++i){s.d[i]=regs[i];s.a[i]=regs[8+i];}s.pc=pc;s.carry=carry_of(carry);return s;}
bool regs_equal(const State&s,const std::uint32_t*want){for(unsigned int i=0;i<8;++i)if(s.d[i]!=want[i]||s.a[i]!=want[8+i])return false;return true;}
void dump_regs(const State&s,const std::uint32_t*want){
 for(unsigned int i=0;i<8;++i){if(s.d[i]!=want[i])std::cerr<<" d"<<i<<" "<<s.d[i]<<" want "<<want[i]<<"\n";if(s.a[i]!=want[8+i])std::cerr<<" a"<<i<<" "<<s.a[i]<<" want "<<want[8+i]<<"\n";}}
unsigned int success_count=0,kept_c=0,single_count=0,path_count=0,chain_count=0,declared_count=0,error_count=0,moved_fail=0;
// Runs one success fixture with the declared incoming C and checks pc / registers / digest / PVC page / bank / no port.
bool run_fixture(const Fixture&f,unsigned int carry,Bytes&ram,State&s,Out&o,unsigned long long&d){
 ram=base_ram(f.puts);s=state_of(f.regs,f.entry,carry);
 if(!run(ram,s,f.stop,o)){std::cerr<<f.name<<"\n";return false;}
 d=digest(ram,s,o.dev.bank_base,o.reads,o.status);
 return s.pc==f.stop&&o.status==ms5::AnimationMachineReturned&&o.dev.bank_base==0x200000&&o.dev.pvc==pvc_base()&&o.ports.empty()&&o.reads==0;}
void fixtures(){
 for(unsigned int k=0;k<FIXTURE_COUNT;++k){const Fixture&f=FIXTURES[k];
  if(f.error!=NULL){Bytes ram=base_ram(f.puts);State s=state_of(f.regs,f.entry,f.carry);fails_at(ram,s,f.fail,f.error,f.stop);++error_count;if(f.fail!=f.entry)++moved_fail;continue;}
  Bytes ram;State s;Out o;unsigned long long d=0;
  if(!run_fixture(f,f.carry,ram,s,o,d)||!regs_equal(s,f.out)||d!=f.digest){
   std::cerr<<f.name<<" mismatch pc "<<std::hex<<s.pc<<" digest "<<d<<"\n";dump_regs(s,f.out);check(false,"fixture",f.entry);}
  if(s.carry!=carry_of(f.c))std::cerr<<f.name<<" carry "<<s.carry<<" want "<<f.c<<"\n";
  check(s.carry==carry_of(f.c),"carry after the fixture",f.entry);
  if(f.c)++kept_c;
  ++success_count;
  if(f.single==1)++single_count;else if(f.single==0)++path_count;else if(f.single==2)++chain_count;else if(f.single==3)++declared_count;}
}
// Block table: every start (the consumers excepted) is the entry of at least one single-block fixture; each single-block fixture runs with the incoming C
// Unknown / Clear / Set: the state and the successor never depend on the incoming C (no consumer is entered directly), the C after the block follows the
// contract classification.
void block_table(){
 unsigned int starts_seen=0;
 for(unsigned int i=0;i<START_COUNT;++i){
  check(in_ranges(STARTS[i]),"start inside the routed ranges",STARTS[i]);
  unsigned int entered=0;
  for(unsigned int k=0;k<FIXTURE_COUNT;++k){const Fixture&f=FIXTURES[k];if(f.single!=1||f.entry!=STARTS[i])continue;++entered;
   check(!is_consumer(f.entry),"single fixture never enters a consumer",f.entry);
   check(f.c==carry_after(f.entry,0),"single row C follows the classification",f.entry);
   for(unsigned int c=0;c<3;++c){Bytes ram;State s;Out o;unsigned long long d=0;
    const bool ok=run_fixture(f,c,ram,s,o,d)&&regs_equal(s,f.out)&&d==f.digest;
    if(!ok)std::cerr<<f.name<<" carry "<<c<<" mismatch\n";check(ok,"single fixture with every incoming C",f.entry,c);
    check(s.carry==carry_of(carry_after(f.entry,c)),"C after the block follows the classification for every incoming C",f.entry,c);}}
  if(is_consumer(STARTS[i]))check(entered==0,"consumer has no single fixture",STARTS[i]);
  else{check(entered>0,"start entered by a single-block fixture",STARTS[i]);++starts_seen;}}
 check(starts_seen+CONSUMER_COUNT==START_COUNT,"every non-consumer start entered");
 // Exits: every routed exit of the unit is a stop of some row (stop-only).
 for(unsigned int e=0;e<EXIT_COUNT;++e){unsigned int seen=0;
  for(unsigned int k=0;k<FIXTURE_COUNT;++k)if(FIXTURES[k].error==NULL&&FIXTURES[k].stop==EXITS[e])++seen;
  if(seen==0)std::cerr<<std::hex<<"exit never a stop "<<EXITS[e]<<"\n";
  check(seen>0,"exit stop covered",EXITS[e]);}
 // Every success row stops at a unit start, at one of the exits or at a computed table target (stop-only).
 for(unsigned int k=0;k<FIXTURE_COUNT;++k){const Fixture&f=FIXTURES[k];if(f.error!=NULL)continue;
  const bool ok=is_start(f.stop)||in_list(EXITS,EXIT_COUNT,f.stop)||is_target(f.stop);
  if(!ok)std::cerr<<f.name<<" stop "<<std::hex<<f.stop<<"\n";
  check(ok,"stop is a start, a routed exit or a table target",f.stop);}
}
// Consumers: the declared known C (both values) and the real producers decide; the same state with an Unknown C is a checked error.
void consumers(){
 for(unsigned int i=0;i<CONSUMER_COUNT;++i){unsigned int seen=0,chain=0;
  for(unsigned int k=0;k<FIXTURE_COUNT;++k){const Fixture&f=FIXTURES[k];if(f.error!=NULL)continue;
   if(f.single==3&&f.entry==CONSUMERS[i][0]){seen|=1U<<(f.carry-1U);
    check(f.stop==(f.carry==1U?CONSUMERS[i][1]:CONSUMERS[i][2])&&f.c==carry_after(f.entry,f.carry),"declared C picks the consumer successor",f.entry,f.carry);}
   if(f.single==2&&f.entry==chain_from(CONSUMERS[i][0])&&(f.stop==CONSUMERS[i][1]||f.stop==CONSUMERS[i][2])){
    check(f.c==1U||f.c==2U,"producer chain: a known C at the consumer successor",f.entry,f.stop);
    if(CONSUMERS[i][1]!=CONSUMERS[i][2])check(f.c==(f.stop==CONSUMERS[i][1]?1U:2U),"producer chain: the consumer successor gives the C",f.entry,f.stop);
    chain|=f.c;}}
  check(seen==3U,"both declared C values per consumer",CONSUMERS[i][0]);
  if(in_list(CHAINED,CHAINED_COUNT,CONSUMERS[i][0]))check(chain==3U,"real producer chain (both C values)",CONSUMERS[i][0]);
  // Unknown C: checked error, every output preserved (also with a RAM stop that the run never reaches).
  Bytes ram=base_ram("");State s;s.pc=CONSUMERS[i][0];s.a[6]=NODE;s.a[5]=A5;s.a[7]=SP;
  reject(ram,s,0x10fe40,"objects fr4 caller requires known carry");}
}
// Every other even PC of the routed ranges is rejected by the executor (the failing PC is the entry); odd PCs first; the unrouted probes in RAM.
void interior(){
 unsigned int even=0,inside=0;
 for(unsigned int r=0;r<RANGE_COUNT;++r)for(std::uint32_t pc=RANGES[r][0];pc<RANGES[r][1];pc+=2){++even;
  if(is_start(pc))continue;Bytes ram=base_ram("");State s;s.pc=pc;s.a[6]=NODE;s.a[5]=A5;s.a[7]=SP;s.carry=ms5::AnimationCarrySet;
  reject(ram,s,STOP,"unsupported animation objects fr4 PC");++inside;}
 check(even==EVEN_COUNT&&inside==EVEN_COUNT-START_COUNT&&inside==908U,"interior even PCs",inside);
 // Rollback probes only in work RAM 10fe00..10fefe (code never executes in RAM; F4 unit test boundary convention).
 const std::uint32_t outside[]={0x10fe00,0x10fe6c,0x10fefe};
 for(unsigned int i=0;i<sizeof(outside)/sizeof(outside[0]);++i){Bytes ram=base_ram("");State s;s.pc=outside[i];s.a[6]=NODE;s.a[7]=SP;reject(ram,s,STOP,"unsupported animation machine PC");}
 // A unit RTS whose return LONG is a RAM probe rolls the whole run back (8790a RTS, cc818 RTS, 87a8a RTS, ccab6 SNE; CLR ...; RTS, cdc1c MOVE.L; RTS).
 const std::uint32_t rts[]={0x8790a,0xcc818,0x87a8a,0xccab6,0xcdc1c};
 for(unsigned int i=0;i<sizeof(rts)/sizeof(rts[0]);++i){Bytes ram=base_ram("");put(ram,SP,4,0x10fe40);State s;s.pc=rts[i];
  s.a[5]=A5;s.a[6]=NODE;s.a[7]=SP;s.carry=ms5::AnimationCarrySet;reject(ram,s,STOP,"unsupported animation machine PC");}
 for(unsigned int r=0;r<RANGE_COUNT;++r){const std::uint32_t odd[]={RANGES[r][0]+1,RANGES[r][1]-1};
  for(unsigned int i=0;i<2;++i){Bytes ram=base_ram("");State s;s.pc=odd[i];s.a[6]=NODE;s.a[7]=SP;reject(ram,s,STOP,"unaligned animation machine PC");}}
}
// Zero-step: a run whose stop is its entry returns at once with nothing changed, for every start and every incoming C (consumers included).
void zero_step(){
 for(unsigned int i=0;i<START_COUNT;++i)for(unsigned int c=0;c<3;++c){
  Bytes ram=base_ram("10e000:0102030405060708");State s;s.pc=STARTS[i];s.a[6]=NODE;s.a[5]=A5;s.a[7]=SP;s.carry=carry_of(c);s.d[3]=0x12345678;
  const Bytes before=ram;const State old=s;Out o;
  check(run(ram,s,STARTS[i],o)&&ram==before&&same(s,old)&&o.status==ms5::AnimationMachineReturned&&o.ports.empty()&&o.reads==0&&
   o.dev.pvc==pvc_base()&&o.dev.bank_base==0x200000,"zero-step run",STARTS[i],c);}
}
State st(std::uint32_t pc){State s;s.pc=pc;s.a[0]=CHILD;s.a[1]=REC1;s.a[5]=A5;s.a[6]=NODE;s.a[7]=SP;return s;}
// Explicit rules (hand-written, the mutation-sensitive integer details; the constants were computed by hand): the computed jumps cc7a0 / cc822 for
// every index 0..1a (stop-only at the table entry, the WORD index), through cc784 (BYTE 5e cleared, BYTE 15 bit 7 picks the table, >= 1b -> cdc1c),
// the in-unit landings of a direct entry (1b -> cc818 RTS, 92 -> cca76, ff -> ccba8 stop-only), the sign-extending MOVEM.W pops of 7310c and the
// push order of 730fa, the BVS of 73520 (both signs), the MOVEQ / MOVE.W zero extension and the ADDI.W wrap of 73506, ASR.W / SWAP / ASR.L of 734be
// and 734ac, LSL.L / SWAP / ADDI.W of 7308e, ANDI.L / SUBI.L of 72f90, ASR.L #5 of 73392, NEG.W / LSR.W / the signed BLE of 87a78 and 87a6c, the
// negative WORD index of 87986 and cc610 (extra typed bytes; the zero-extended offsets are not mapped), the BYTE writes of cca80 / ccab6 next to
// their neighbours, SNE of ccab6, SUBQ.W / ANDI.W of 73482 with BSET / BCLR, LONG 9e of 7349c, the unsigned compares of 73304 / cc798, ANDI.B of
// 730d8, the WORD arithmetic of 73296 / 732ac (EOR.W, NEG.L), the LONG arithmetic of 730ba, and the data PCs next to the ranges (dispatcher error).
void rules(){
 // cc7a0 / cc822: ANDI.W #ff (the high BYTE of the WORD is cleared, the upper WORD stays), 4 x index, PC := table + index (stop-only targets).
 for(std::uint32_t k=0;k<27U;++k){
  {Bytes ram=base_ram("");State s=st(0xcc7a0);s.d[0]=0x1234ab00U|k;Out o;
   check(run(ram,s,0xcc7acU+4U*k,o)&&s.pc==0xcc7acU+4U*k&&s.d[0]==(0x12340000U|(4U*k))&&s.a[7]==SP,"cc7a0 table index",k);}
  {Bytes ram=base_ram("");State s=st(0xcc822);s.d[0]=0x1234ab00U|k;Out o;
   check(run(ram,s,0xcc82eU+4U*k,o)&&s.pc==0xcc82eU+4U*k&&s.d[0]==(0x12340000U|(4U*k)),"cc822 table index",k);}
  // through cc784: MOVE.B 5e(A6),D0; MOVE.B #0,5e(A6); BTST.B #7,15(A6): set -> cc798 / table 1, clear -> cc81a / table 2.
  for(unsigned int t=0;t<2;++t){Bytes ram=base_ram("");put(ram,NODE+0x5e,1,k);put(ram,NODE+0x5f,1,0x77);put(ram,NODE+0x15,1,t==0U?0x80U:0x7fU);
   const std::uint32_t want=(t==0U?0xcc7acU:0xcc82eU)+4U*k;State s=st(0xcc784);s.d[0]=0x12345600U;Out o;
   check(run(ram,s,want,o)&&get(ram,NODE+0x5e,1)==0U&&get(ram,NODE+0x5f,1)==0x77U&&s.d[0]==(0x12340000U|(4U*k)),"cc784 table",k,t);}}
 // cc784 with BYTE 5e >= 1b (unsigned): cdc1c writes the callback LONG cdc24 and returns.
 {const std::uint32_t v[]={0x1b,0xff};
  for(unsigned int k=0;k<2;++k){Bytes ram=base_ram("");put(ram,NODE+0x5e,1,v[k]);put(ram,NODE+0x15,1,0x80);State s=st(0xcc784);Out o;
   check(run(ram,s,STOP,o)&&get(ram,NODE,4)==0xcdc24U&&get(ram,NODE+0x5e,1)==0U&&s.a[7]==SP+4U,"cc784 >= 1b -> cdc1c",v[k]);}}
 // Direct entries with D0.B >= 1b: 1b lands on the start cc818 (RTS, the original runs it), 92 (cc822) on the start cca76, ff (cc7a0) outside the unit
 // at ccba8 (stop-only; 1c / 93 land inside a block: error rows).
 {Bytes ram=base_ram("");State s=st(0xcc7a0);s.d[0]=0x1b;Out o;check(run(ram,s,STOP,o)&&s.a[7]==SP+4U,"cc7a0 1b -> cc818 RTS");}
 {Bytes ram=base_ram("");State s=st(0xcc822);s.d[0]=0x92;Out o;check(run(ram,s,0xcca76,o)&&s.d[0]==0x248U,"cc822 92 -> cca76");}
 {Bytes ram=base_ram("");State s=st(0xcc7a0);s.d[0]=0xff;Out o;check(run(ram,s,0xccba8,o)&&s.d[0]==0x3fcU,"cc7a0 ff -> ccba8");}
 // 7310c: MOVEM.W (A7)+,D2-D3 sign-extends (8000 -> ffff8000 into D2 from the lower address, 7fff -> 00007fff), BSR.W 70036 (return LONG 73114).
 {Bytes ram=base_ram("");put(ram,SP-4U,2,0x8000);put(ram,SP-2U,2,0x7fff);State s=st(0x7310c);s.d[2]=0x12345678U;s.d[3]=0x9abcdef0U;s.a[7]=SP-4U;Out o;
  check(run(ram,s,0x70036,o)&&s.d[2]==0xffff8000U&&s.d[3]==0x7fffU&&s.a[7]==SP-4U&&get(ram,SP-4U,4)==0x73114U,"7310c MOVEM.W sign extension");}
 // 730fa: D0.W := 40 + WORD 42 (10) = 50 (upper WORD 1234 stays), D1.W := WORD 46; MOVEM.W D0-D1,-(A7) puts D0.W at the lower address.
 {Bytes ram=base_ram("");put(ram,NODE+0x42,2,0x10);put(ram,NODE+0x46,2,0x8001);State s=st(0x730fa);s.d[0]=0x12340040U;s.d[1]=0x9abcdef0U;Out o;
  check(run(ram,s,0x4bc04,o)&&s.d[0]==0x12340050U&&s.d[1]==0x9abc8001U&&get(ram,SP-4U,2)==0x50U&&get(ram,SP-2U,2)==0x8001U&&s.a[7]==SP-8U&&
   get(ram,SP-8U,4)==0x7310cU,"730fa MOVEM.W push order");}
 // 73520: D2 = 40000000 + LONG 92 (3fffffff) = 7fffffff -> LONG 92; + LONG 8e (1) overflows (V) -> 7353c, LONG 8e kept; LONG 8e = 0: no overflow, 73538
 // stores 7fffffff; D2 = 80000000 + LONG 8e (ffffffff) overflows negative -> LONG 8e kept.
 {const std::uint32_t d2[]={0x40000000U,0x40000000U,0x80000000U},l92[]={0x3fffffffU,0x3fffffffU,0},l8e[]={1,0,0xffffffffU};
  const std::uint32_t want8e[]={1,0x7fffffffU,0xffffffffU},want92[]={0x7fffffffU,0x7fffffffU,0x80000000U};
  for(unsigned int k=0;k<3;++k){Bytes ram=base_ram("");put(ram,NODE+0x92,4,l92[k]);put(ram,NODE+0x8e,4,l8e[k]);State s=st(0x73520);s.d[0]=0;s.d[1]=0;s.d[2]=d2[k];Out o;
   check(run(ram,s,0x7353c,o)&&get(ram,NODE+0x8e,4)==want8e[k]&&get(ram,NODE+0x92,4)==want92[k]&&s.d[2]==want92[k]+l8e[k],"73520 BVS",k);}}
 // 73520: LSL.L #1 drops bit 31 (8000ffff -> 0001fffe); ASR.L #6 of 12345678 = 0048d159; ADD.W: d159 + fffe -> d157 (upper WORD 0048 stays);
 // D2 = 9abcdef0 - 0048d157 = 9a740d99 -> LONG 92 and (no overflow) LONG 8e.
 {Bytes ram=base_ram("");State s=st(0x73520);s.d[0]=0x8000ffffU;s.d[1]=0x12345678U;s.d[2]=0x9abcdef0U;Out o;
  check(run(ram,s,0x7353c,o)&&s.d[0]==0x0001fffeU&&s.d[1]==0x0048d157U&&s.d[2]==0x9a740d99U&&get(ram,NODE+0x92,4)==0x9a740d99U&&get(ram,NODE+0x8e,4)==0x9a740d99U,
   "73520 LSL.L / ASR.L / ADD.W / SUB.L");}
 // 73506: MOVEQ #0,D0; MOVE.W 8c(A6),D0 zero-extends; ADDI.W #77 wraps in the WORD (ff89 -> 0000, ff88 -> ffff); ASR.L #6 of D2; LONG 92 >= 0 -> 7351e.
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,2,0xff89);put(ram,NODE+0x92,4,0x40);State s=st(0x73506);s.d[0]=0x12345678U;s.d[2]=0x80000000U;Out o;
  check(run(ram,s,0x7351e,o)&&s.d[0]==0U&&get(ram,NODE+0x8c,2)==0U&&s.d[2]==0xfe000000U&&s.d[1]==0x40U,"73506 ADDI.W wrap");}
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,2,0xff88);put(ram,NODE+0x92,4,0x80000000U);State s=st(0x73506);s.d[0]=0x12345678U;Out o;
  check(run(ram,s,0x73520,o)&&s.d[0]==0xffffU&&get(ram,NODE+0x8c,2)==0xffffU&&s.d[1]==0x80000000U,"73506 MOVEQ / MOVE.W zero extension, BMI");}
 // 734be: D0.W = 7fff + 1 + 8000 = 0000 (WORD wrap), SWAP -> 00001234, ASR.L #8 -> 12; ASR.W #1 of D3.W 8001 = c000 (sign kept, upper WORD stays) -> 734ce.
 {Bytes ram=base_ram("");State s=st(0x734be);s.d[0]=0x12347fffU;s.d[1]=1;s.d[3]=0x55558001U;Out o;
  check(run(ram,s,0x734ce,o)&&s.d[0]==0x12U&&s.d[3]==0x5555c000U,"734be ADDI.W / SWAP / ASR.L / ASR.W");}
 // 734ac: ASR.W #1 of 8001 = c000 (negative) -> 734b2 NEG.W -> 4000 (upper WORD 1234 stays) -> 734b4.
 {Bytes ram=base_ram("");State s=st(0x734ac);s.d[1]=0x12348001U;Out o;check(run(ram,s,0x734b4,o)&&s.d[1]==0x12344000U,"734ac ASR.W / NEG.W");}
 // 7308e: LSL.L #6 of 03ffffff = ffffffc0, SWAP = ffc0ffff, ADDI.W #80 = ffc0007f -> WORD 2c; LONG 8e := LONG 42; MOVE.L #730a6,(A6) enters 730a6.
 {Bytes ram=base_ram("");put(ram,NODE+0x42,4,0x12345678U);State s=st(0x7308e);s.d[0]=0x03ffffffU;Out o;
  check(run(ram,s,0x730a6,o)&&s.d[0]==0xffc0007fU&&get(ram,NODE+0x2c,2)==0x7fU&&get(ram,NODE+0x8e,4)==0x12345678U&&get(ram,NODE,4)==0x730a6U,"7308e LSL.L / SWAP / ADDI.W");}
 // 72f90: ANDI.L #ff (ffffff7f -> 7f), SUBI.L #80 -> ffffffff -> LONG 92; BYTE 83 = 0 -> 73008.
 {Bytes ram=base_ram("");State s=st(0x72f90);s.d[0]=0xffffff7fU;Out o;check(run(ram,s,0x73008,o)&&s.d[0]==0xffffffffU&&get(ram,NODE+0x92,4)==0xffffffffU,"72f90 ANDI.L / SUBI.L");}
 // 73392: LONG 36 = 1f + ASR.L(0 - 1f, 5) = 1f - 1 = 1e; LONG 3a = fff00020 + ASR.L(fff00000 - fff00020, 5) = fff0001f; D0 = ffffffff; JSR 4be34.
 {Bytes ram=base_ram("");put(ram,NODE+0x64,4,0);put(ram,NODE+0x36,4,0x1f);put(ram,NODE+0x3a,4,0xfff00020U);State s=st(0x73392);Out o;
  check(run(ram,s,0x4be34,o)&&get(ram,NODE+0x36,4)==0x1eU&&get(ram,NODE+0x3a,4)==0xfff0001fU&&s.d[0]==0xffffffffU&&get(ram,SP-4U,4)==0x733b6U,"73392 ASR.L #5");}
 // 87a78: NEG.W fff8 = 0008, LSR.W #1 = 4 <= 4 (signed) -> 87a88 (upper WORD 1234 stays); NEG.W 8000 = 8000, LSR.W #1 = 4000 > 4 -> 87a84.
 {Bytes ram=base_ram("");State s=st(0x87a78);s.d[1]=0x1234fff8U;Out o;check(run(ram,s,0x87a88,o)&&s.d[1]==0x12340004U,"87a78 NEG.W / LSR.W / BLE");}
 {Bytes ram=base_ram("");State s=st(0x87a78);s.d[1]=0x1234fff8U;Out o;const bool ok=run(ram,s,0x87a84,o);check(!(ok&&s.pc==0x87a84),"87a78 BLE takes 87a88 directly at the tie (87a84 is not entered)");}
{Bytes ram=base_ram("");State s=st(0x732dc);s.a[6]=0x1fff9aU;Out o;check(run(ram,s,0x732ee,o)&&s.pc==0x732ee,"732dc TST.W 64(A6) reads one WORD (last WORD before the bank window)");}
{Bytes ram=base_ram("");State s=st(0x87a78);s.d[1]=0x9abc8000U;Out o;check(run(ram,s,0x87a84,o)&&s.d[1]==0x9abc4000U,"87a78 LSR.W is unsigned");}
 // 87a6c: WORD 3a = fff0 -> D1.W = 10 >> 1 = 8 > 4 -> 4; D0.W = 13 + 4 = 17 (upper WORDs stay); RTS.
 {Bytes ram=base_ram("");put(ram,NODE+0x3a,2,0xfff0);State s=st(0x87a6c);s.d[0]=0xabcd0000U;s.d[1]=0x55550000U;Out o;
  check(run(ram,s,STOP,o)&&s.d[0]==0xabcd0017U&&s.d[1]==0x55550004U,"87a6c frame number");}
 // 87986: D1.W = 4 x 2000 = WORD 8000, sign-extended: LONG (2a5000 - 8000) = 29d000 (extra typed bytes there; the zero-extended 2ad000 is not mapped).
 {Physical rom=ROM;ms5::PhysicalRomResource r;r.source_rom_offset=0x29d000;r.data=hex_bytes("0010fe30");rom.push_back(r);
  Bytes ram=base_ram("");State s=st(0x87986);s.d[0]=0xabcd2000U;s.d[1]=0x55550000U;
  check(run_rom(rom,ram,s,0x49f8c)&&s.a[1]==0x10fe30U&&s.d[1]==0x55558000U&&s.d[0]==0xabcd0100U&&s.a[0]==NODE+0x26U&&get(ram,NODE+0x20,2)==0xbaU&&
   get(ram,NODE+0x22,4)==synthetic(0x200080,4)&&get(ram,SP-4U,4)==0x879b6U,"87986 negative WORD index");}
 // cc610: WORD 8c = 2000 -> 4 x 2000 = WORD 8000, sign-extended: LONG (cdf3e - 8000) = c5f3e (extra typed bytes -> RAM record 10fe60); the sound WORD
 // 8000 is negative -> cc632 (BEQ / BPL pair).
 {Physical rom=ROM;ms5::PhysicalRomResource r;r.source_rom_offset=0xc5f3e;r.data=hex_bytes("0010fe60");rom.push_back(r);
  Bytes ram=base_ram("");put(ram,NODE+0x8c,2,0x2000);put(ram,0x10fe60,2,0x8000);State s=st(0xcc610);s.d[0]=0xabcd1234U;
  check(run_rom(rom,ram,s,0xcc632)&&s.a[0]==0x10fe60U&&s.d[0]==0xabcd8000U,"cc610 negative WORD index");}
 // cc654: record WORD +2 (index 1 -> ADD.W -> 2): 0 -> cc694, 7fff -> cc68a.
 {Bytes ram=base_ram("");put(ram,NODE+0x8c,2,2);put(ram,0x10fe50,2,0x8000);put(ram,0x10fe52,2,0);State s=st(0xcc654);Out o;
  check(run(ram,s,0xcc694,o)&&s.a[0]==0x10fe50U&&(s.d[0]&0xffffU)==0U,"cc654 record +2 zero");
  Bytes ram2=base_ram("");put(ram2,NODE+0x8c,2,2);put(ram2,0x10fe52,2,0x7fff);State s2=st(0xcc654);Out o2;check(run(ram2,s2,0xcc68a,o2)&&(s2.d[0]&0xffffU)==0x7fffU,"cc654 record +2 positive");}
 // cca80: MOVE.B #0,76 / #ff,7b (the neighbours 77 / 7a stay), LONG 82 := A0, LONG 86 := A1, WORD 8a := D1.W, WORD 8c := D2.W.
 {Bytes ram=base_ram("");put(ram,NODE+0x76,2,0xffff);put(ram,NODE+0x7a,2,0x5a00);State s=st(0xcca80);s.a[0]=0x12345678U;s.a[1]=0x9abcdef0U;s.d[1]=0x9abc8001U;
  s.d[2]=0x55550005U;Out o;
  check(run(ram,s,0xcca9c,o)&&get(ram,NODE+0x76,2)==0x00ffU&&get(ram,NODE+0x7a,2)==0x5affU&&get(ram,NODE+0x82,4)==0x12345678U&&get(ram,NODE+0x86,4)==0x9abcdef0U&&
   get(ram,NODE+0x8a,2)==0x8001U&&get(ram,NODE+0x8c,2)==0x0005U,"cca80 BYTE / LONG / WORD stores");}
 // cca76: BSET.B #6,61(A6): old bit 0 -> cca80 (the bit is now set), old bit 1 -> cca9c.
 {Bytes ram=base_ram("");put(ram,NODE+0x61,1,0xbf);State s=st(0xcca76);Out o;check(run(ram,s,0xcca80,o)&&get(ram,NODE+0x61,1)==0xffU,"cca76 BSET old 0");
  Bytes ram2=base_ram("");put(ram2,NODE+0x61,1,0x40);State s2=st(0xcca76);Out o2;check(run(ram2,s2,0xcca9c,o2)&&get(ram2,NODE+0x61,1)==0x40U,"cca76 BSET old 1");}
 // ccab6: SNE.B 78(A6) after BTST.B #7,15(A6) (80 -> ff, 7f -> 00); the BYTE / LONG clears leave 76 / 7b alone.
 {const std::uint32_t v[]={0x80,0x7f};
  for(unsigned int k=0;k<2;++k){Bytes ram=base_ram("10e064:11223344,10e076:11a1a2a3a4a5a6a7a8a9aaabacadae");put(ram,NODE+0x15,1,v[k]);State s=st(0xccab6);Out o;
   check(run(ram,s,STOP,o)&&get(ram,NODE+0x78,1)==(k==0U?0xffU:0U)&&get(ram,NODE+0x76,1)==0x11U&&get(ram,NODE+0x77,1)==0U&&get(ram,NODE+0x79,1)==0U&&
    get(ram,NODE+0x7a,1)==0U&&get(ram,NODE+0x7b,1)==0xa5U&&get(ram,NODE+0x7c,1)==0U&&get(ram,NODE+0x7d,1)==0U&&get(ram,NODE+0x7e,4)==0U&&
    get(ram,NODE+0x82,1)==0xacU&&get(ram,NODE+0x64,4)==0U,"ccab6 SNE / CLR",k);}}
 // 7347a: BYTE 62 = 2 -> D0.W = ff02 - 1 = ff01, ANDI.W #1 = 1 -> 73496 BCLR #0; 7349c: LONG 9e := the callback LONG, (A6) := 72d42; JSR 48502.
 {Bytes ram=base_ram("");put(ram,NODE,4,0x72f8a);put(ram,NODE+0x62,1,2);put(ram,NODE+0x15,1,0xff);State s=st(0x7347a);s.d[0]=0x1234ff00U;Out o;
  check(run(ram,s,0x48502,o)&&s.d[0]==0x12340001U&&get(ram,NODE+0x15,1)==0xfeU&&get(ram,NODE+0x9e,4)==0x72f8aU&&get(ram,NODE,4)==0x72d42U,"7347a BCLR / LONG 9e");}
 {Bytes ram=base_ram("");put(ram,NODE+0x62,1,1);State s=st(0x7347a);s.d[0]=0x1234ff00U;Out o;
  check(run(ram,s,0x48502,o)&&s.d[0]==0x12340000U&&get(ram,NODE+0x15,1)==1U,"7347a BSET");}
 // 73304: CMPI.W #180,46(A6); BCS (unsigned): 8000 -> 7330e (LONG 3a := 8a000), 17f -> 73316 (LONG 3a kept).
 {Bytes ram=base_ram("");put(ram,NODE+0x46,2,0x8000);put(ram,NODE+0x3a,4,0x11111111U);State s=st(0x73304);Out o;
  check(run(ram,s,0x73316,o)&&get(ram,NODE+0x3a,4)==0x8a000U,"73304 unsigned 8000");
  Bytes ram2=base_ram("");put(ram2,NODE+0x46,2,0x17f);put(ram2,NODE+0x3a,4,0x11111111U);State s2=st(0x73304);Out o2;
  check(run(ram2,s2,0x73316,o2)&&get(ram2,NODE+0x3a,4)==0x11111111U,"73304 unsigned 17f");}
 // cc798: CMPI.B #1b,D0; BCC (unsigned): ff -> cdc1c (a signed compare would take cc7a0).
 {Bytes ram=base_ram("");State s=st(0xcc798);s.d[0]=0x123456ffU;Out o;check(run(ram,s,0xcdc1c,o),"cc798 unsigned ff");}
 // 730d8: ANDI.B #7,D0 (f8 -> 00, upper bits stay) -> BEQ.W 71a80 (stop-only, routed).
 {Bytes ram=base_ram("");State s=st(0x730d8);s.d[0]=0x123456f8U;Out o;check(run(ram,s,0x71a80,o)&&s.d[0]==0x12345600U,"730d8 ANDI.B");}
 // 73296: D2.W = (c001 << 2) + 7fff = 0004 + 7fff = 8003 (upper WORD stays), D3.W := WORD 46, D0.W := ff; BSR.W 70036 (return LONG 732ac).
 {Bytes ram=base_ram("");put(ram,NODE+0x64,2,0xc001);put(ram,NODE+0x42,2,0x7fff);put(ram,NODE+0x46,2,0x8000);State s=st(0x73296);
  s.d[0]=0x55667788U;s.d[2]=0x12345678U;s.d[3]=0x9abcdef0U;Out o;
  check(run(ram,s,0x70036,o)&&s.d[2]==0x12348003U&&s.d[3]==0x9abc8000U&&s.d[0]==0x556600ffU&&get(ram,SP-4U,4)==0x732acU,"73296 LSL.W / ADD.W");}
 // 732ac: (WORD 8e - WORD 42) EOR WORD 64: 10 - 11 = ffff, ^ 8000 = 7fff >= 0 -> 732c2; ^ 0000 = ffff < 0 -> 732be NEG.L 64.
 {Bytes ram=base_ram("");put(ram,NODE+0x8e,2,0x10);put(ram,NODE+0x42,2,0x11);put(ram,NODE+0x64,4,0x80001234U);State s=st(0x732ac);s.d[0]=0x12345678U;
  s.d[1]=0x9abcdef0U;Out o;check(run(ram,s,0x732c2,o)&&s.d[0]==0x12347fffU&&s.d[1]==0x9abc8000U&&get(ram,NODE+0x64,4)==0x80001234U,"732ac EOR.W");
  Bytes ram2=base_ram("");put(ram2,NODE+0x8e,2,0x10);put(ram2,NODE+0x42,2,0x11);put(ram2,NODE+0x64,4,0x00001234U);State s2=st(0x732ac);Out o2;
  check(run(ram2,s2,0x732c2,o2)&&get(ram2,NODE+0x64,4)==0xffffedccU,"732ac NEG.L 64");}
 // 730ba: D0 = (10000 - 0) + (fffe0000 << 3 = fff00000) = fff10000, EOR fffe0000 = 000f0000 >= 0 -> 730ea.
 {Bytes ram=base_ram("");put(ram,NODE+0x8e,4,0x10000);put(ram,NODE+0x42,4,0);put(ram,NODE+0x64,4,0xfffe0000U);State s=st(0x730ba);Out o;
  check(run(ram,s,0x730ea,o)&&s.d[0]==0x000f0000U&&s.d[1]==0xfffe0000U&&s.d[2]==0xfff00000U,"730ba LONG arithmetic");}
 // The data PCs next to the ranges are not routed (dispatcher error).
 const std::uint32_t data[]={0x87a8c,0x72d5e};
 for(unsigned int i=0;i<sizeof(data)/sizeof(data[0]);++i){Bytes ram=base_ram("");State s;s.pc=data[i];s.a[6]=NODE;s.a[7]=SP;
  check(!in_ranges(data[i]),"data PC outside the routed ranges",data[i]);reject(ram,s,STOP,"unsupported animation machine PC");}
}
